# -*- coding: utf-8 -*-
# Original explanatory content for the 12 basic English tenses (vi / ru / ja). Hand-written for NihongoLife.
T = []
def add(id, n, f, use, sig, ex, err):
    T.append(dict(id=id, name=dict(en=n[0], vi=n[1], ru=n[2], ja=n[3]),
                  formula=dict(affirmative=f[0], negative=f[1], question=f[2]),
                  usage=dict(vi=use[0], ru=use[1], ja=use[2]), signals=sig,
                  examples=[dict(en=e[0], vi=e[1], ru=e[2], ja=e[3]) for e in ex],
                  commonMistake=dict(vi=err[0], ru=err[1], ja=err[2])))

add("present_simple", ("Present Simple","Hiện tại đơn","Настоящее простое","現在形（単純現在）"),
 ("S + V(s/es)  — I/you/we/they work · he/she/it works","S + do/does + not + V  — She does not work","Do/Does + S + V ?  — Does she work?"),
 (["Thói quen, việc lặp đi lặp lại (every day, usually).","Sự thật hiển nhiên, chân lý (The sun rises in the east).","Lịch trình cố định (The train leaves at 7)."],
  ["Привычки и регулярные действия (every day, usually).","Общеизвестные факты (The sun rises in the east).","Расписания (The train leaves at 7)."],
  ["習慣・繰り返される行動（every day, usually）。","変わらない事実・真理（The sun rises in the east）。","決まった予定・時刻表（The train leaves at 7）。"]),
 ["every day","usually","often","always","never","on Sundays","twice a week"],
 [("I drink coffee every morning.","Tôi uống cà phê mỗi sáng.","Я пью кофе каждое утро.","私は毎朝コーヒーを飲みます。"),
  ("The shop opens at nine.","Cửa hàng mở cửa lúc chín giờ.","Магазин открывается в девять.","お店は9時に開きます。"),
  ("Water boils at 100 degrees.","Nước sôi ở 100 độ.","Вода кипит при 100 градусах.","水は100度で沸騰します。")],
 ("Quên thêm -s/-es ở ngôi thứ ba số ít: ✗ She work → ✓ She works. Phủ định/nghi vấn dùng does + động từ nguyên mẫu: ✗ Does she works → ✓ Does she work.",
  "Забывают -s/-es в 3-м лице ед. числа: ✗ She work → ✓ She works. После does глагол без -s: ✗ Does she works → ✓ Does she work.",
  "三人称単数の -s/-es の付け忘れ：✗ She work → ✓ She works。does の後は原形：✗ Does she works → ✓ Does she work。"))

add("present_continuous", ("Present Continuous","Hiện tại tiếp diễn","Настоящее длительное","現在進行形"),
 ("S + am/is/are + V-ing","S + am/is/are + not + V-ing","Am/Is/Are + S + V-ing ?"),
 (["Hành động đang diễn ra ngay lúc nói (now, at the moment).","Hành động tạm thời quanh thời điểm hiện tại (this week).","Kế hoạch chắc chắn trong tương lai gần (I am meeting him tonight)."],
  ["Действие, происходящее прямо сейчас (now, at the moment).","Временное действие в текущий период (this week).","Твёрдый план на ближайшее будущее (I am meeting him tonight)."],
  ["今まさに行われている動作（now, at the moment）。","今の時期だけの一時的な状況（this week）。","近い未来の確定した予定（I am meeting him tonight）。"]),
 ["now","right now","at the moment","today","this week","Look!","Listen!"],
 [("She is cooking dinner now.","Cô ấy đang nấu bữa tối.","Она сейчас готовит ужин.","彼女は今、夕食を作っています。"),
  ("We are staying in Phu Quoc this week.","Tuần này chúng tôi đang ở Phú Quốc.","На этой неделе мы остановились на Фукуоке.","今週、私たちはフーコック島に滞在しています。"),
  ("I am flying to Tokyo tomorrow.","Ngày mai tôi bay đi Tokyo.","Завтра я лечу в Токио.","私は明日東京へ飛びます。")],
 ("Dùng tiếp diễn với động từ trạng thái (know, like, want): ✗ I am knowing → ✓ I know. Đừng quên động từ to be: ✗ He working → ✓ He is working.",
  "С глаголами состояния (know, like, want) длительное не употребляют: ✗ I am knowing → ✓ I know. Не пропускайте to be: ✗ He working → ✓ He is working.",
  "状態動詞（know, like, want）は進行形にしない：✗ I am knowing → ✓ I know。be動詞の脱落に注意：✗ He working → ✓ He is working。"))

add("present_perfect", ("Present Perfect","Hiện tại hoàn thành","Настоящее совершённое","現在完了形"),
 ("S + have/has + V3 (past participle)","S + have/has + not + V3","Have/Has + S + V3 ?"),
 (["Hành động đã xảy ra, còn liên quan đến hiện tại (I have lost my key).","Trải nghiệm trong đời (Have you ever been to Japan?).","Việc bắt đầu trong quá khứ và kéo dài đến nay với for/since."],
  ["Действие в прошлом, важное для настоящего (I have lost my key).","Жизненный опыт (Have you ever been to Japan?).","Состояние, длящееся до сейчас, с for/since."],
  ["過去の出来事が今に影響している（鍵をなくしてしまった）。","これまでの経験（日本に行ったことがありますか）。","過去から今まで続く状態（for / since を使う）。"]),
 ["already","yet","just","ever","never","so far","for","since","recently"],
 [("I have finished my homework.","Tôi đã làm xong bài tập.","Я закончил домашнее задание.","私は宿題を終えました。"),
  ("She has visited Kyoto twice.","Cô ấy đã đến Kyoto hai lần.","Она дважды бывала в Киото.","彼女は京都を2回訪れたことがあります。"),
  ("They have lived here since 2020.","Họ sống ở đây từ năm 2020.","Они живут здесь с 2020 года.","彼らは2020年からここに住んでいます。")],
 ("Dùng present perfect với mốc thời gian đã qua: ✗ I have seen him yesterday → ✓ I saw him yesterday. Phân biệt for (khoảng thời gian) và since (mốc thời gian).",
  "Нельзя использовать с указанием прошедшего времени: ✗ I have seen him yesterday → ✓ I saw him yesterday. Различайте for (период) и since (момент начала).",
  "過去の時点を示す語とは使えない：✗ I have seen him yesterday → ✓ I saw him yesterday。for（期間）と since（起点）を区別する。"))

add("present_perfect_continuous", ("Present Perfect Continuous","Hiện tại hoàn thành tiếp diễn","Настоящее совершённо-длительное","現在完了進行形"),
 ("S + have/has + been + V-ing","S + have/has + not + been + V-ing","Have/Has + S + been + V-ing ?"),
 (["Nhấn mạnh quá trình kéo dài từ quá khứ đến hiện tại (I have been waiting for an hour).","Hành động vừa kết thúc nhưng còn thấy kết quả (You are wet — have you been running?).","Thường đi với for, since, all day, lately."],
  ["Подчёркивает длительность действия до настоящего момента (I have been waiting for an hour).","Действие только что закончилось, но виден результат (You are wet — have you been running?).","Часто с for, since, all day, lately."],
  ["過去から今まで続く動作の継続を強調（1時間ずっと待っている）。","今終わったばかりで結果が見える（濡れているね、走っていたの？）。","for, since, all day, lately とよく一緒に使う。"]),
 ["for + period","since + point in time","all day","lately","recently","how long"],
 [("I have been studying English for two hours.","Tôi đã học tiếng Anh được hai tiếng rồi.","Я уже два часа учу английский.","私は2時間ずっと英語を勉強しています。"),
  ("It has been raining since morning.","Trời mưa từ sáng đến giờ.","Дождь идёт с самого утра.","朝からずっと雨が降っています。"),
  ("How long have you been working here?","Bạn làm việc ở đây được bao lâu rồi?","Как давно вы здесь работаете?","ここでどのくらい働いていますか。")],
 ("Động từ trạng thái không dùng được: ✗ I have been knowing → ✓ I have known. Đừng dùng been thiếu: ✗ I have studying → ✓ I have been studying.",
  "Глаголы состояния не употребляются: ✗ I have been knowing → ✓ I have known. Не забывайте been: ✗ I have studying → ✓ I have been studying.",
  "状態動詞は使えない：✗ I have been knowing → ✓ I have known。been の脱落に注意：✗ I have studying → ✓ I have been studying。"))

add("past_simple", ("Past Simple","Quá khứ đơn","Прошедшее простое","過去形"),
 ("S + V2 (past form)","S + did + not + V","Did + S + V ?"),
 (["Hành động đã xảy ra và kết thúc hẳn ở một thời điểm xác định trong quá khứ.","Chuỗi hành động nối tiếp trong quá khứ (I got up, ate, and left).","Thói quen trong quá khứ (When I was a child, I played outside)."],
  ["Завершённое действие в определённый момент прошлого.","Последовательность действий в прошлом (I got up, ate, and left).","Привычка в прошлом (When I was a child, I played outside)."],
  ["過去の特定の時点で終わった出来事。","過去に起こった一連の動作（起きて、食べて、出かけた）。","過去の習慣（子どもの頃は外で遊んだ）。"]),
 ["yesterday","last week","two days ago","in 2019","when I was young"],
 [("I visited Hoi An last month.","Tháng trước tôi đã đến Hội An.","В прошлом месяце я ездил в Хойан.","先月、私はホイアンを訪れました。"),
  ("She didn't come to the party.","Cô ấy đã không đến bữa tiệc.","Она не пришла на вечеринку.","彼女はパーティーに来ませんでした。"),
  ("Did you see the doctor yesterday?","Hôm qua bạn có đi khám bác sĩ không?","Вы вчера ходили к врачу?","昨日、医者に診てもらいましたか。")],
 ("Sau did dùng động từ nguyên mẫu: ✗ Did you went → ✓ Did you go. Động từ bất quy tắc phải học thuộc: go → went, buy → bought.",
  "После did глагол в начальной форме: ✗ Did you went → ✓ Did you go. Неправильные глаголы нужно учить: go → went, buy → bought.",
  "did の後は原形：✗ Did you went → ✓ Did you go。不規則動詞は暗記：go → went, buy → bought。"))

add("past_continuous", ("Past Continuous","Quá khứ tiếp diễn","Прошедшее длительное","過去進行形"),
 ("S + was/were + V-ing","S + was/were + not + V-ing","Was/Were + S + V-ing ?"),
 (["Hành động đang diễn ra tại một thời điểm xác định trong quá khứ (at 8 pm last night).","Hành động đang diễn ra thì bị một hành động khác cắt ngang (I was cooking when he called).","Hai hành động diễn ra song song (while)."],
  ["Действие, длившееся в определённый момент прошлого (at 8 pm last night).","Длительное действие, прерванное другим (I was cooking when he called).","Два параллельных действия (while)."],
  ["過去のある時点で進行中だった動作（昨夜8時に）。","進行中の動作に別の出来事が割り込む（料理中に電話が来た）。","同時に進行していた二つの動作（while）。"]),
 ["while","when","at 8 o'clock yesterday","all evening","at that moment"],
 [("I was reading when the lights went out.","Tôi đang đọc sách thì mất điện.","Я читал, когда погас свет.","本を読んでいるときに停電しました。"),
  ("They were playing football at five o'clock.","Lúc năm giờ họ đang chơi bóng đá.","В пять часов они играли в футбол.","5時に彼らはサッカーをしていました。"),
  ("While she was cooking, he was washing the dishes.","Trong khi cô ấy nấu ăn thì anh ấy rửa bát.","Пока она готовила, он мыл посуду.","彼女が料理をしている間、彼は皿を洗っていました。")],
 ("Hành động ngắn cắt ngang dùng quá khứ đơn, hành động dài dùng tiếp diễn: ✓ I was walking when I saw him. Chọn was/were đúng theo chủ ngữ.",
  "Короткое прерывающее действие — Past Simple, длинное — Past Continuous: ✓ I was walking when I saw him. Выбирайте was/were по подлежащему.",
  "短い出来事は過去形、長く続く動作は過去進行形：✓ I was walking when I saw him。主語に合わせて was/were を選ぶ。"))

add("past_perfect", ("Past Perfect","Quá khứ hoàn thành","Предпрошедшее (Past Perfect)","過去完了形"),
 ("S + had + V3","S + had + not + V3","Had + S + V3 ?"),
 (["Hành động xảy ra trước một hành động/mốc khác trong quá khứ.","Thường đi với before, after, by the time, already.","Dùng để giải thích nguyên nhân của một sự việc trong quá khứ."],
  ["Действие, завершившееся до другого действия или момента в прошлом.","Часто с before, after, by the time, already.","Объясняет причину прошлого события."],
  ["過去のある時点より前に完了していた出来事。","before, after, by the time, already とよく使う。","過去の出来事の原因を説明する。"]),
 ["before","after","by the time","already","just","when"],
 [("When we arrived, the film had already started.","Khi chúng tôi đến thì phim đã bắt đầu rồi.","Когда мы пришли, фильм уже начался.","私たちが着いたとき、映画はもう始まっていました。"),
  ("She had never seen snow before she moved to Japan.","Trước khi chuyển đến Nhật, cô ấy chưa từng thấy tuyết.","Она никогда не видела снега до переезда в Японию.","日本に引っ越すまで、彼女は雪を見たことがありませんでした。"),
  ("I was tired because I had worked all day.","Tôi mệt vì đã làm việc cả ngày.","Я устал, потому что работал весь день.","一日中働いたので疲れていました。")],
 ("Đừng dùng cho hành động không có mối liên hệ trước–sau: ✗ I had eaten breakfast. (không có mốc) → ✓ I ate breakfast. Hành động xảy ra sau dùng quá khứ đơn.",
  "Не используйте без связи «раньше — позже»: ✗ I had eaten breakfast. → ✓ I ate breakfast. Более позднее действие — в Past Simple.",
  "前後関係がないときは使わない：✗ I had eaten breakfast. → ✓ I ate breakfast。後に起きたことは過去形で表す。"))

add("past_perfect_continuous", ("Past Perfect Continuous","Quá khứ hoàn thành tiếp diễn","Предпрошедшее длительное","過去完了進行形"),
 ("S + had + been + V-ing","S + had + not + been + V-ing","Had + S + been + V-ing ?"),
 (["Nhấn mạnh hành động đã kéo dài liên tục trước một mốc trong quá khứ.","Giải thích nguyên nhân/kết quả nhìn thấy ở mốc quá khứ (Her eyes were red; she had been crying).","Thường có for/since + mốc quá khứ."],
  ["Подчёркивает длительность действия до момента в прошлом.","Объясняет видимый результат в прошлом (Her eyes were red; she had been crying).","Часто с for/since и прошлым моментом."],
  ["過去のある時点までずっと続いていた動作を強調。","過去に見えた結果の理由を説明（目が赤かった。泣いていたのだ）。","過去の時点を基準に for / since をよく使う。"]),
 ["for + period","since","before","by the time","all day"],
 [("He had been waiting for an hour when the bus finally came.","Anh ấy đã đợi một tiếng khi xe buýt cuối cùng cũng đến.","Он ждал уже час, когда наконец пришёл автобус.","バスがやっと来たとき、彼は1時間待っていました。"),
  ("They were tired because they had been walking all day.","Họ mệt vì đã đi bộ cả ngày.","Они устали, потому что весь день шли пешком.","彼らは一日中歩いていたので疲れていました。"),
  ("I had been studying for two hours before I took a break.","Tôi đã học hai tiếng liền trước khi nghỉ giải lao.","Я занимался два часа, прежде чем сделать перерыв.","休憩する前に、私は2時間ずっと勉強していました。")],
 ("Nhầm với past perfect: ✗ I had been know → ✓ I had known. Cần đủ had been + V-ing.",
  "Путают с Past Perfect и забывают been: ✗ I had studying → ✓ I had been studying.",
  "had been + V-ing の形を崩さない：✗ I had studying → ✓ I had been studying。"))

add("future_simple", ("Future Simple (will)","Tương lai đơn","Будущее простое","未来形（will）"),
 ("S + will + V","S + will + not (won't) + V","Will + S + V ?"),
 (["Quyết định tức thời lúc nói (I'll have the noodles).","Dự đoán, ý kiến về tương lai (I think it will rain).","Lời hứa, đề nghị, lời hứa giúp đỡ (I will help you)."],
  ["Спонтанное решение в момент речи (I'll have the noodles).","Предположение о будущем (I think it will rain).","Обещание, предложение помощи (I will help you)."],
  ["その場で決めた意思（麺にします）。","未来の予測・意見（雨が降ると思う）。","約束・申し出（手伝います）。"]),
 ["tomorrow","next week","in two days","soon","I think","probably","perhaps"],
 [("I will call you tomorrow.","Ngày mai tôi sẽ gọi cho bạn.","Я позвоню вам завтра.","明日、電話します。"),
  ("It will probably rain tonight.","Tối nay có lẽ trời sẽ mưa.","Сегодня вечером, вероятно, пойдёт дождь.","今夜はたぶん雨が降るでしょう。"),
  ("Will you help me with this bag?","Bạn giúp tôi xách túi này được không?","Поможете мне с этой сумкой?","このバッグを手伝ってくれますか。")],
 ("Sau will dùng động từ nguyên mẫu, không thêm to/-s: ✗ She will goes → ✓ She will go. Với kế hoạch đã định sẵn thường dùng be going to.",
  "После will — глагол без to и без -s: ✗ She will goes → ✓ She will go. Для заранее принятых планов обычно be going to.",
  "will の後は原形（to や -s は付けない）：✗ She will goes → ✓ She will go。決まっていた計画には be going to を使うことが多い。"))

add("future_continuous", ("Future Continuous","Tương lai tiếp diễn","Будущее длительное","未来進行形"),
 ("S + will + be + V-ing","S + will + not + be + V-ing","Will + S + be + V-ing ?"),
 (["Hành động sẽ đang diễn ra tại một thời điểm xác định trong tương lai (At 8 pm I will be driving).","Hỏi lịch trình một cách lịch sự (Will you be using the car?).","Hành động tương lai như một phần của kế hoạch tự nhiên."],
  ["Действие, которое будет в процессе в определённый момент будущего (At 8 pm I will be driving).","Вежливый вопрос о планах (Will you be using the car?).","Действие как естественная часть планов."],
  ["未来のある時点で進行中の動作（午後8時には運転中だろう）。","予定を丁寧にたずねる（車を使いますか）。","自然な流れとして起こる未来の動作。"]),
 ["at this time tomorrow","at 8 pm tonight","next Sunday at noon","this time next week"],
 [("This time tomorrow, I will be lying on the beach.","Giờ này ngày mai tôi sẽ đang nằm trên bãi biển.","Завтра в это время я буду лежать на пляже.","明日の今ごろ、私はビーチで寝ているでしょう。"),
  ("She will be working at 9 pm tonight.","Chín giờ tối nay cô ấy sẽ đang làm việc.","Сегодня в девять вечера она будет работать.","今夜9時、彼女は仕事中でしょう。"),
  ("Will you be using the computer this afternoon?","Chiều nay bạn có dùng máy tính không?","Вы будете пользоваться компьютером днём?","今日の午後、パソコンを使いますか。")],
 ("Quên be: ✗ I will working → ✓ I will be working. Không dùng cho động từ trạng thái: ✗ I will be knowing.",
  "Забывают be: ✗ I will working → ✓ I will be working. Не используется с глаголами состояния.",
  "be の脱落に注意：✗ I will working → ✓ I will be working。状態動詞には使わない。"))

add("future_perfect", ("Future Perfect","Tương lai hoàn thành","Будущее совершённое","未来完了形"),
 ("S + will + have + V3","S + will + not + have + V3","Will + S + have + V3 ?"),
 (["Hành động sẽ hoàn tất trước một mốc trong tương lai (By Friday I will have finished).","Thường đi với by + mốc thời gian, by the time.","Dự đoán điều đã xảy ra vào thời điểm đó."],
  ["Действие, которое будет завершено к определённому моменту (By Friday I will have finished).","Часто с by + момент времени, by the time.","Предположение о том, что к тому моменту уже произойдёт."],
  ["未来のある時点までに完了している動作（金曜までに終えているだろう）。","by + 時点、by the time とよく使う。","その時点までに起こっているはずのことの予測。"]),
 ["by + time","by the time","by next Friday","by 2030","before"],
 [("By next Friday, I will have finished this report.","Đến thứ Sáu tới tôi sẽ hoàn thành báo cáo này.","К следующей пятнице я закончу этот отчёт.","来週の金曜までに、この報告書を仕上げているでしょう。"),
  ("They will have arrived by noon.","Đến trưa họ sẽ đến nơi rồi.","К полудню они уже приедут.","彼らは正午までに到着しているでしょう。"),
  ("Will you have eaten by the time I come?","Lúc tôi đến thì bạn đã ăn xong chưa?","Вы уже поедите к моему приходу?","私が行くまでに食べ終わっているでしょうか。")],
 ("Sau by the time không dùng will: ✗ by the time you will arrive → ✓ by the time you arrive. Vẫn cần have + V3 sau will.",
  "После by the time нет will: ✗ by the time you will arrive → ✓ by the time you arrive. После will нужно have + V3.",
  "by the time の節に will は使わない：✗ by the time you will arrive → ✓ by the time you arrive。will の後は have + V3。"))

add("future_perfect_continuous", ("Future Perfect Continuous","Tương lai hoàn thành tiếp diễn","Будущее совершённо-длительное","未来完了進行形"),
 ("S + will + have + been + V-ing","S + will + not + have + been + V-ing","Will + S + have + been + V-ing ?"),
 (["Nhấn mạnh độ dài của hành động tính đến một mốc trong tương lai (By June I will have been working here for ten years).","Thường đi với by + mốc, for + khoảng thời gian.","Ít dùng, chủ yếu trong văn viết/trang trọng."],
  ["Подчёркивает длительность действия к определённому моменту в будущем (By June I will have been working here for ten years).","Часто с by + момент и for + период.","Употребляется редко, чаще в письменной речи."],
  ["未来のある時点までに動作がどれだけ続いているかを強調（6月で10年間働いていることになる）。","by + 時点、for + 期間とよく使う。","使用頻度は低く、書き言葉が中心。"]),
 ["by + time","for + period","by the time","next year"],
 [("By June, I will have been working here for ten years.","Đến tháng Sáu tôi sẽ làm việc ở đây được mười năm.","К июню я буду работать здесь уже десять лет.","6月で、私はここで10年間働いていることになります。"),
  ("At noon, she will have been studying for four hours.","Đến trưa cô ấy sẽ học được bốn tiếng liên tục.","К полудню она будет заниматься уже четыре часа.","正午には、彼女は4時間勉強し続けていることになります。"),
  ("Will they have been waiting long by then?","Đến lúc đó họ sẽ đợi lâu rồi chứ?","Они будут ждать уже долго к тому времени?","そのころには、彼らはもう長い間待っているでしょうか。")],
 ("Thiếu been hoặc have: ✗ I will have working → ✓ I will have been working. Đây là thì dài nhất — luôn kiểm tra will + have + been + V-ing.",
  "Пропускают have или been: ✗ I will have working → ✓ I will have been working. Проверяйте: will + have + been + V-ing.",
  "have や been の抜け：✗ I will have working → ✓ I will have been working。will + have + been + V-ing の順を確認。"))